	num_t fn = static_cast<num_t>(n);

	// Initialize x, y, b
	traverser(b, x, y).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = static_cast<num_t>(0);
		y[state] = static_cast<num_t>(0);

		num_t val = static_cast<num_t>(i + 1);
		val = val / fn / static_cast<num_t>(2.0);
		val += static_cast<num_t>(4.0);

		b[state] = val;
	});

	// Initialize A: lower triangular with 1s on diagonal and 0 above
	auto len_j = A | get_length<'j'>();

	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i = get_index<'i'>(s_i);

		// j = 0..i : A[i][j] = (-j % n)/n + 1
		trav_i.order(noarr::slice<'j'>(0, i + 1)).for_each([=](auto s_ij) {
			auto j = get_index<'j'>(s_ij);

			int jj = static_cast<int>(j);
			int tmp = -jj;
			int mod = tmp % n; // n > 0

			num_t val = static_cast<num_t>(mod) / static_cast<num_t>(n) + static_cast<num_t>(1);
			A[s_ij] = val;
		});

		// j = i+1..n-1 : A[i][j] = 0
		if (i + 1 <= len_j) {
			auto length = len_j - (i + 1);
			if (length > 0) {
				trav_i.order(noarr::slice<'j'>(i + 1, length)).for_each([=](auto s_ij) {
					A[s_ij] = static_cast<num_t>(0);
				});
			}
		}

		// A[i][i] = 1
		A[noarr::idx<'i', 'j'>(i, i)] = static_cast<num_t>(1);
	});

	// Make the matrix positive semi-definite using a temporary B
	auto B = noarr::bag(A.structure());

	// B = 0
	traverser(B).for_each([=](auto s) {
		B[s] = static_cast<num_t>(0);
	});

	// B[r][s] += A[r][t] * A[s][t]
	for (int t = 0; t < n; ++t) {
		traverser(B).for_each([=](auto sb) {
			auto [r, s] = get_indices<'i', 'j'>(sb);

			num_t art = A[noarr::idx<'i', 'j'>(r, static_cast<std::size_t>(t))];
			num_t ast = A[noarr::idx<'i', 'j'>(s, static_cast<std::size_t>(t))];

			B[sb] += art * ast;
		});
	}

	// Copy B back into A
	traverser(A, B).for_each([=](auto s) {
		A[s] = B[s];
	});
