	auto len_i = A | get_length<'i'>();
	auto len_j = A | get_length<'j'>();

#pragma scop
	// LU decomposition in-place in A
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i = get_index<'i'>(s_i);

		// First inner loop: j = 0 .. i-1
		if (i > 0) {
			trav_i.order(noarr::slice<'j'>(0, i)).for_each([=](auto s_ij) {
				num_t w = A[s_ij];

				auto [ii, jj] = get_indices<'i', 'j'>(s_ij);
				for (std::size_t k = 0; k < jj; ++k) {
					w -= A[noarr::idx<'i', 'j'>(ii, k)] * A[noarr::idx<'i', 'j'>(k, jj)];
				}

				num_t a_jj = A[noarr::idx<'i', 'j'>(jj, jj)];
				A[s_ij] = w / a_jj;
			});
		}

		// Second inner loop: j = i .. N-1
		auto length_j = len_j - i; // len_j >= i
		trav_i.order(noarr::slice<'j'>(i, length_j)).for_each([=](auto s_ij) {
			num_t w = A[s_ij];

			auto [ii, jj] = get_indices<'i', 'j'>(s_ij);
			for (std::size_t k = 0; k < ii; ++k) {
				w -= A[noarr::idx<'i', 'j'>(ii, k)] * A[noarr::idx<'i', 'j'>(k, jj)];
			}

			A[s_ij] = w;
		});
	});

