	traverser(A, b, y).template for_dims<'i'>([=](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i = get_index<'i'>(s_i);

		num_t w = b[s_i];

		if (i > 0) {
			trav_i.order(noarr::slice<'j'>(0, i)).for_each([&](auto s_ij) {
				w -= A[s_ij] * y[s_ij]; // y ignores 'j' in the state
			});
