	// Traverse i in logical order N-1..0 using a forward traverser with reindexing
	traverser(y).for_each([=](auto s_iter) {
		std::size_t iter = get_index<'i'>(s_iter);
		std::size_t i = len_i - 1 - iter; // maps 0..N-1 -> N-1..0

		auto s_i = noarr::idx<'i'>(i);

