#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// Square matrices, indexed by (i, j)
	DEFINE_PROTO_STRUCT(matrix_layout, j_vec ^ i_vec);
	// 1D vectors, indexed by i
	DEFINE_PROTO_STRUCT(vector_layout, i_vec);
} tuning;


// Array initialization
void init_array(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Initialize vectors x, y, b
	num_t fn = static_cast<num_t>(b | get_length<'i'>());

	traverser(b, x, y).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = static_cast<num_t>(0);
		y[state] = static_cast<num_t>(0);
		b[state] = (static_cast<num_t>(i + 1) / fn / static_cast<num_t>(2.0)) + static_cast<num_t>(4.0);
	});

	// Initialize matrix A to a unit-lower-triangular pattern
	auto n_i = static_cast<int>(A | get_length<'i'>());

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		int j_int = static_cast<int>(j);
		int n_int = n_i;

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			int num = (-j_int % n_int);
			A[state] = static_cast<num_t>(num) / static_cast<num_t>(n_int) + static_cast<num_t>(1);
		} else if (j > i) {
			// Upper part set to 0
			A[state] = static_cast<num_t>(0);
		} else {
			// Diagonal
			A[state] = static_cast<num_t>(1);
		}
	});

	// Make the matrix positive semi-definite using B = A * A^T
	auto B = noarr::bag(A.structure());

	// B[r][s] = 0
	traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	auto n_cols = A | get_length<'j'>();

	// B[r][s] += sum_t A[r][t] * A[s][t]
	traverser(B).for_each([&](auto state) {
		auto [r, s] = get_indices<'i', 'j'>(state);
		num_t sum = static_cast<num_t>(0);

		for (std::size_t t = 0; t < n_cols; ++t) {
			auto rt_state = idx<'i', 'j'>(r, t);
			auto st_state = idx<'i', 'j'>(s, t);
			sum += A[rt_state] * A[st_state];
		}

		B[state] = sum;
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}


// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	auto N = A | get_length<'i'>();

#pragma scop
	// LU decomposition of A in-place
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto i_state = trav_i.state();
		std::size_t i = get_index<'i'>(i_state);
		num_t w;

		// Compute L part (j < i)
		for (std::size_t j = 0; j < i; ++j) {
			auto ij_state = i_state + idx<'j'>(j);
			w = A[ij_state];

			for (std::size_t k = 0; k < j; ++k) {
				auto ik_state = i_state + idx<'j'>(k);
				auto kj_state = idx<'i'>(k) + idx<'j'>(j);
				w -= A[ik_state] * A[kj_state];
			}

			auto jj_state = idx<'i'>(j) + idx<'j'>(j);
			A[ij_state] = w / A[jj_state];
		}

		// Compute U part (j >= i)
		for (std::size_t j = i; j < N; ++j) {
			auto ij_state = i_state + idx<'j'>(j);
			w = A[ij_state];

			for (std::size_t k = 0; k < i; ++k) {
				auto ik_state = i_state + idx<'j'>(k);
				auto kj_state = idx<'i'>(k) + idx<'j'>(j);
				w -= A[ik_state] * A[kj_state];
			}

			A[ij_state] = w;
		}
	});

	// Forward substitution: Ly = b
	traverser(A, b, y).template for_dims<'i'>([=](auto trav_i) {
		auto i_state = trav_i.state();
		std::size_t i = get_index<'i'>(i_state);
		num_t w = b[i_state];

		for (std::size_t j = 0; j < i; ++j) {
			auto ij_state = i_state + idx<'j'>(j);
			auto j_state = idx<'i'>(j);
			w -= A[ij_state] * y[j_state];
		}

		y[i_state] = w;
	});

	// Back substitution: Ux = y (in reverse i)
	traverser(A, x, y).template for_dims<'i'>([=](auto trav_i) {
		auto fwd_state = trav_i.state();
		std::size_t pos = get_index<'i'>(fwd_state);
		std::size_t i = N - 1 - pos; // map forward traversal to reverse index
		auto i_state = idx<'i'>(i);

		num_t w = y[i_state];

		for (std::size_t j = i + 1; j < N; ++j) {
			auto ij_state = i_state + idx<'j'>(j);
			auto j_state = idx<'i'>(j);
			w -= A[ij_state] * x[j_state];
		}

		auto ii_state = i_state + idx<'j'>(i);
		x[i_state] = w / A[ii_state];
	});
