	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto si = trav_i.state();
		auto i = get_index<'i'>(si);

		// j from 0 to i (inclusive)
		auto j_prefix_struct = scalar<char>() ^ vector<'j'>(i + 1);
		traverser(j_prefix_struct).for_each([=](auto sj) {
			auto j = get_index<'j'>(sj);

			auto a_ij_state = idx<'i', 'j'>(i, j);

			int j_int = static_cast<int>(j);
			int term = (-j_int) % n; // matches C's (-j % n)

			A[a_ij_state] = static_cast<num_t>(term) / static_cast<num_t>(n) + static_cast<num_t>(1);
		});

		// j from i+1 to n-1
		if (i + 1 < n_len) {
			auto remaining = n_len - (i + 1);
			auto j_suffix_struct = scalar<char>() ^ vector<'j'>(remaining);

			traverser(j_suffix_struct).for_each([=](auto sj) {
				auto j_off = get_index<'j'>(sj);
				auto j = i + 1 + j_off;

				auto a_ij_state = idx<'i', 'j'>(i, j);
				A[a_ij_state] = static_cast<num_t>(0);
			});
