	// B[r][s] = sum_t A[r][t] * A[s][t]
	auto B = noarr::make_bag(A.structure());

	// Initialize B to zeros:
	// for (r = 0; r < n; ++r)
	//   for (s = 0; s < n; ++s)
	//     B[r][s] = 0;
	traverser(B).for_each([=](auto state) {
