	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < _PB_N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
