			auto lower_trav = trav_i.order(noarr::slice<'j'>(0, i));

			lower_trav.for_each([=](auto sij) {
				num_t w = A[sij];
				auto j = get_index<'j'>(sij);

				// k from 0 to j-1
				if (j > 0) {
					auto k_struct = scalar<char>() ^ vector<'k'>(j);
					traverser(k_struct).for_each([&](auto sk) {
						auto k = get_index<'k'>(sk);

						auto aik_state = idx<'i', 'j'>(i, k);
						auto akj_state = idx<'i', 'j'>(k, j);

						w -= A[aik_state] * A[akj_state];
					});
				}

				auto ajj_state = idx<'i', 'j'>(j, j);
				A[sij] = w / A[ajj_state];
			});
		}

		// Second j-loop: j from i to N-1
		auto upper_trav = trav_i.order(noarr::slice<'j'>(i, n_len - i));

		upper_trav.for_each([=](auto sij) {
			num_t w = A[sij];
			auto j = get_index<'j'>(sij);

			// k from 0 to i-1
			if (i > 0) {
				auto k_struct = scalar<char>() ^ vector<'k'>(i);
				traverser(k_struct).for_each([&](auto sk) {
					auto k = get_index<'k'>(sk);

					auto aik_state = idx<'i', 'j'>(i, k);
					auto akj_state = idx<'i', 'j'>(k, j);

					w -= A[aik_state] * A[akj_state];
				});
			}

			A[sij] = w;
		});
	});

