	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	traverser(A, b, y).template for_dims<'i'>([=](auto trav_i) {
		auto si = trav_i.state();
		auto i = get_index<'i'>(si);

		num_t w = b[si];

		if (i > 0) {
			auto j_struct = scalar<char>() ^ vector<'j'>(i);
			traverser(j_struct).for_each([&](auto sj) {
				auto j = get_index<'j'>(sj);

				auto aij_state = idx<'i', 'j'>(i, j);
				auto yj_state = idx<'i'>(j);

				w -= A[aij_state] * y[yj_state];
			});
		}

		auto yi_state = idx<'i'>(i);
		y[yi_state] = w;
	});

	// Backward substitution: solve U * x = y
	// for (i = _PB_N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < _PB_N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We traverse a helper index r = 0..N-1 and map to i = N-1-r to preserve
	// the original dependency order.
	auto helper_r = scalar<char>() ^ vector<'r'>(n_len);

	traverser(helper_r).for_each([=](auto sr) {
		auto r = get_index<'r'>(sr);
		auto i = n_len - 1 - r;

		auto yi_state = idx<'i'>(i);
		num_t w = y[yi_state];

		if (i + 1 < n_len) {
			auto len_j = n_len - (i + 1);
			auto j_struct = scalar<char>() ^ vector<'j'>(len_j);

			traverser(j_struct).for_each([&](auto sj) {
				auto j_off = get_index<'j'>(sj);
				auto j = i + 1 + j_off;

				auto aij_state = idx<'i', 'j'>(i, j);
				auto xj_state = idx<'i'>(j);

